export type ParsedSweepTransitInstruction<
  TProgram extends string = typeof RECUR_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    admin: TAccountMetas[0];
    config: TAccountMetas[1];
    transit: TAccountMetas[2];
    transitAta: TAccountMetas[3];
    treasuryAta: TAccountMetas[4];
    tokenProgram: TAccountMetas[5];
  };
  data: SweepTransitInstructionData;
};

export function parseSweepTransitInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedSweepTransitInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 6) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 6,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      admin: getNextAccount(),
      config: getNextAccount(),
      transit: getNextAccount(),
      transitAta: getNextAccount(),
      treasuryAta: getNextAccount(),
      tokenProgram: getNextAccount(),
    },
    data: getSweepTransitInstructionDataDecoder().decode(instruction.data),
  };
}
